
CREATE TEMP TABLE _migration (title_match TEXT, new_url TEXT, new_notes TEXT);

-- Update repository_url where it's NULL and we have a URL
UPDATE books b
SET repository_url = m.new_url
FROM _migration m
WHERE LOWER(TRIM(b.title)) = LOWER(m.title_match)
  AND m.new_url != ''
  AND b.repository_url IS NULL;

-- Update notes where it's empty and we have notes  
UPDATE books b
SET notes = m.new_notes
FROM _migration m
WHERE LOWER(TRIM(b.title)) = LOWER(m.title_match)
  AND m.new_notes != ''
  AND (b.notes IS NULL OR b.notes = '');

DROP TABLE _migration;

SELECT 
  (SELECT COUNT(*) FROM books WHERE repository_url IS NOT NULL) as books_with_url,
  (SELECT COUNT(*) FROM books WHERE notes IS NOT NULL AND notes != '') as books_with_notes;
